const $=s=>document.querySelector(s);let selected=0,layout=1;const names=['Character I','Character II','Character III','Character IV'];const chars=names.map((name,i)=>({name,sample:i,url:null,position:50,zoom:100,empty:false}));const layoutNames=['ARCHIVE','RHYTHM','PRISM','FILM'];let dragIndex=null;let toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
function render(){const panels=$('#panels');panels.replaceChildren();$('#slotTabs').replaceChildren();chars.forEach((c,i)=>{const b=document.createElement('button');b.className='panel'+(i===selected?' active':'');b.draggable=true;b.setAttribute('aria-label',`${i+1}번 슬롯 ${c.name||'빈 슬롯'} 선택`);b.setAttribute('aria-pressed',i===selected);const pic=document.createElement('span');pic.className='portrait';if(!c.empty){pic.style.backgroundImage=`url("${c.url||'reference.png'}")`;if(c.url){pic.style.backgroundSize='cover';pic.style.backgroundPosition=`${c.position}% center`}else{pic.style.backgroundSize='auto 150%';pic.style.backgroundPosition=`${[0,33,66,100][c.sample]+(c.position-50)*.15}% 42%`}pic.style.transform=`scale(${c.zoom/100})`}else{pic.classList.add('empty');pic.textContent='＋'}const num=document.createElement('span');num.className='panel-number';num.textContent=`0${i+1}`;const caption=document.createElement('span');caption.className='panel-caption';const tag=document.createElement('small');tag.textContent='CHARACTER';const title=document.createElement('strong');title.textContent=c.empty?'Your character':c.name;caption.append(tag,title);b.append(pic,num,caption);b.onclick=()=>selectCharacter(i);b.ondragstart=e=>{dragIndex=i;e.dataTransfer.setData('text/plain',String(i));e.dataTransfer.effectAllowed='move'};b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();if(dragIndex!==null){[chars[i],chars[dragIndex]]=[chars[dragIndex],chars[i]];selected=i;dragIndex=null;render()}};b.ondragend=()=>dragIndex=null;panels.append(b);const tab=document.createElement('button');tab.textContent=`0${i+1}`;tab.className=i===selected?'active':'';tab.setAttribute('aria-label',`${i+1}번 슬롯 편집`);tab.setAttribute('aria-pressed',i===selected);tab.onclick=()=>{selected=i;render()};$('#slotTabs').append(tab)});const c=chars[selected];$('#name').value=c.name;$('#position').value=c.position;$('#zoom').value=c.zoom;$('#positionValue').textContent=c.position+'%';$('#zoomValue').textContent=c.zoom+'%';$('#selectedLabel').textContent=`SLOT 0${selected+1}`;$('.sample-note').textContent=c.url?'내 이미지가 적용되었습니다.':c.empty?'빈 슬롯에 캐릭터를 추가해 보세요.':'현재 레퍼런스 이미지로 미리 보고 있어요.'}
function setLayout(n){if(!Number.isInteger(n)||n<1||n>4)throw Error('레이아웃은 1–4 사이여야 합니다.');layout=n;$('#canvas').className=`canvas layout-${n}`;$('#layoutLabel').textContent=`0${n} — ${layoutNames[n-1]}`;document.querySelectorAll('[data-layout]').forEach(b=>{b.classList.toggle('active',+b.dataset.layout===n);b.setAttribute('aria-pressed',+b.dataset.layout===n)})}
document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>setLayout(+b.dataset.layout));$('#name').oninput=e=>{chars[selected].name=e.target.value;const p=$('#panels').children[selected];p.querySelector('strong').textContent=e.target.value};['position','zoom'].forEach(k=>$('#'+k).oninput=e=>{chars[selected][k]=+e.target.value;render()});function move(d){const to=selected+d;if(to<0||to>3){toast('더 이상 이동할 수 없어요.');return}[chars[to],chars[selected]]=[chars[selected],chars[to]];selected=to;render()}$('#left').onclick=()=>move(-1);$('#right').onclick=()=>move(1);$('#clear').onclick=()=>{const c=chars[selected];if(c.url)URL.revokeObjectURL(c.url);Object.assign(c,{url:null,empty:true,name:'',position:50,zoom:100});render()};
async function upload(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('PNG, JPG, WEBP 이미지를 선택해 주세요.');return}if(file.size>10*1024*1024){toast('10MB 이하의 이미지를 선택해 주세요.');return}const slot=selected;const url=URL.createObjectURL(file);const img=new Image();img.src=url;try{await img.decode();const old=chars[slot].url;if(old)URL.revokeObjectURL(old);Object.assign(chars[slot],{url,empty:false,name:file.name.replace(/\.[^.]+$/,'').slice(0,32),position:50,zoom:100});render();toast(`${slot+1}번 슬롯에 캐릭터를 배치했어요.`)}catch{URL.revokeObjectURL(url);toast('이미지를 읽을 수 없어요. 다른 파일을 선택해 주세요.')}}$('#upload').onchange=e=>{upload(e.target.files[0]);e.target.value=''};$('#dropZone').ondragover=e=>e.preventDefault();$('#dropZone').ondrop=e=>{e.preventDefault();upload(e.dataTransfer.files[0])};$('#titleInput').oninput=e=>$('#posterTitle').textContent=e.target.value;document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{$('#canvas').style.backgroundColor=b.dataset.color;document.querySelectorAll('[data-color]').forEach(x=>x.classList.toggle('chosen',x===b))});$('#preview').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#canvas').requestFullscreen()}catch{toast('이 브라우저에서는 전체 화면을 지원하지 않아요.')}};render();setLayout(1);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_character_layout',description:'캐릭터 선택 화면의 레이아웃을 1–4 중 하나로 변경합니다.',inputSchema:{type:'object',properties:{layout:{type:'integer',minimum:1,maximum:4}},required:['layout'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){setLayout(input.layout);return{layout,name:layoutNames[layout-1]}}})).catch(()=>{})}catch{}}

const editPanel=$('#characterEditor'),editToggle=$('#editToggle'),layoutPanel=$('#layoutEditor'),layoutToggle=$('#layoutToggle');
function toggleEditor(open){document.body.classList.toggle('editing',open);editPanel.inert=!open;editToggle.setAttribute('aria-expanded',String(open));if(open){toggleLayout(false,false);$('#closeEditor').focus()}else editToggle.focus()}
function toggleLayout(open,focus=true){document.body.classList.toggle('layout-editing',open);layoutPanel.inert=!open;layoutToggle.setAttribute('aria-expanded',String(open));if(open){document.body.classList.remove('editing');editPanel.inert=true;editToggle.setAttribute('aria-expanded','false');$('#closeLayout').focus()}else if(focus)layoutToggle.focus()}
editToggle.onclick=()=>toggleEditor(!document.body.classList.contains('editing'));$('#closeEditor').onclick=()=>toggleEditor(false);layoutToggle.onclick=()=>toggleLayout(!document.body.classList.contains('layout-editing'));$('#closeLayout').onclick=()=>toggleLayout(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.body.classList.contains('editing'))toggleEditor(false);if(document.body.classList.contains('layout-editing'))toggleLayout(false)}});
function selectCharacter(i){selected=i;render();document.querySelector('.poster-bottom span:last-child').textContent=`0${i+1} / 04`;if(chars[i].empty){toggleEditor(true);return}openCharacterFocus(i)}

const fontStyles=[['Cormorant Garamond','클래식','serif'],['Cinzel','판타지','serif'],['Bodoni Moda','에디토리얼','serif'],['UnifrakturMaguntia','블랙레터','serif'],['Great Vibes','스크립트','cursive'],['Orbitron','SF','sans-serif'],['Bebas Neue','시네마','sans-serif'],['Noto Serif KR','한글 명조','serif'],['Noto Sans KR','한글 고딕','sans-serif'],['Black Han Sans','한글 헤드라인','sans-serif'],['Gowun Batang','고운 바탕','serif'],['Nanum Myeongjo','나눔 명조','serif']];
fontStyles.forEach(([family,label,fallback],i)=>{const b=document.createElement('button');b.type='button';b.className='font-choice'+(!i?' active':'');b.setAttribute('aria-pressed',!i);b.style.fontFamily=`"${family}",${fallback}`;const demo=document.createElement('span');demo.textContent=i<7?'Aa':'가나다';const text=document.createElement('small');text.textContent=label;b.append(demo,text);b.onclick=()=>{$('#posterTitle').style.fontFamily=`"${family}",${fallback}`;document.querySelectorAll('.font-choice').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)})};$('#fontChoices').append(b)});
$('#subtitleInput').oninput=e=>$('#posterSubtitle').textContent=e.target.value;$('#titleSize').oninput=e=>{document.documentElement.style.setProperty('--title-scale',e.target.value/100);$('#titleSizeValue').textContent=e.target.value+'%'};$('#titleSpacing').oninput=e=>{$('#posterTitle').style.letterSpacing=e.target.value+'px';$('#titleSpacingValue').textContent=e.target.value+'px'};$('#titleColor').oninput=e=>$('#posterTitle').style.color=e.target.value;

const focusDialog=$('#characterFocus');let focusExitTimer;let focusHistoryKey=null;
for(let i=0;i<22;i++){const spark=document.createElement('i');spark.className='focus-spark';spark.style.setProperty('--x',((i*43+13)%100)+'%');spark.style.setProperty('--y',((i*31+7)%100)+'%');spark.style.setProperty('--delay',((i%7)*.19)+'s');spark.style.setProperty('--duration',(2.2+(i%5)*.4)+'s');$('#focusSparks').append(spark)}
function openCharacterFocus(i){clearTimeout(focusExitTimer);const c=chars[i];document.body.classList.remove('editing','layout-editing');editPanel.inert=true;layoutPanel.inert=true;editToggle.setAttribute('aria-expanded','false');layoutToggle.setAttribute('aria-expanded','false');const portrait=$('#panels').children[i].querySelector('.portrait');document.querySelectorAll('.shard-art,.focus-backdrop').forEach(el=>{el.style.backgroundImage=portrait.style.backgroundImage;el.style.backgroundPosition=portrait.style.backgroundPosition;el.style.backgroundSize=c.url?'cover':'auto 240%';el.style.setProperty('--portrait-zoom',c.zoom/100)});$('#focusName').textContent=c.name||`Character 0${i+1}`;$('#focusName').style.fontFamily=$('#posterTitle').style.fontFamily;$('#focusSubtitle').textContent=$('#posterTitle').textContent;$('#focusIndex').textContent=`0${i+1} / 04`;focusDialog.classList.remove('leaving');document.body.classList.add('character-focused');focusDialog.showModal();focusDialog.scrollTop=0;$('#focusBack').focus();focusHistoryKey='character-'+Date.now();history.pushState({...history.state,characterFocus:focusHistoryKey},'')}
function finishCharacterFocus(){if(!focusDialog.open)return;focusDialog.classList.add('leaving');document.body.classList.remove('character-focused');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;focusExitTimer=setTimeout(()=>{focusDialog.close();focusDialog.classList.remove('leaving');$('#panels').children[selected]?.focus()},reduced?0:380)}
function backFromCharacter(){if(!focusDialog.open||focusDialog.classList.contains('leaving'))return;if(focusHistoryKey&&history.state?.characterFocus===focusHistoryKey){history.back()}else finishCharacterFocus()}
$('#focusBack').onclick=backFromCharacter;focusDialog.addEventListener('cancel',e=>{e.preventDefault();backFromCharacter()});window.addEventListener('popstate',()=>{focusHistoryKey=null;finishCharacterFocus()});
